// TestBigWordObjectRepeat checks that . repeats diW, daW, ciW and caW.
func TestBigWordObjectRepeat(t *testing.T) {
	runEmptyRangeCases(t, []emptyRangeCase{
		{name: "one line: diW.", content: "a.b c-d e.f g-h", keys: "diW.", text: "c-d e.f g-h", want: Position{0, 0}, reg: anyReg},
		{name: "one line: daW.", content: "a.b c-d e.f g-h", keys: "daW.", text: "e.f g-h", want: Position{0, 0}, reg: anyReg},
		{name: "one line: ciWZ<Esc>w.", content: "a.b c-d e.f g-h", keys: "ciWZ<Esc>w.", text: "Z Z e.f g-h", want: Position{0, 2}, reg: anyReg},
		{name: "one line: caWZ<Esc>.", content: "a.b c-d e.f g-h", keys: "caWZ<Esc>.", text: "Ze.f g-h", want: Position{0, 0}, reg: anyReg},
		{name: "one line: wdiW.", content: "a.b c-d e.f g-h", keys: "wdiW.", text: "c-d e.f g-h", want: Position{0, 0}, reg: anyReg},
		{name: "one line: wdaWb.", content: "a.b c-d e.f g-h", keys: "wdaWb.", text: "e.f g-h", want: Position{0, 0}, reg: anyReg},
		{name: "one line: $daW.", content: "a.b c-d e.f g-h", keys: "$daW.", text: "a.b c-d", want: Position{0, 6}, reg: anyReg},
		{name: "one line: $diWb.", content: "a.b c-d e.f g-h", keys: "$diWb.", text: "a.b c-d  ", want: Position{0, 8}, reg: anyReg},
		{name: "two lines: daWj.", content: "a.b c-d\ne.f g-h", keys: "daWj.", text: "c-d\ng-h", want: Position{1, 0}, reg: anyReg},
		{name: "two lines: diWj.", content: "a.b c-d\ne.f g-h", keys: "diWj.", text: " c-d\n g-h", want: Position{1, 0}, reg: anyReg},
		{name: "two lines: ciWZ<Esc>j0.", content: "a.b c-d\ne.f g-h", keys: "ciWZ<Esc>j0.", text: "Z c-d\nZ g-h", want: Position{1, 0}, reg: anyReg},
		{name: "two lines: jdaWk.", content: "a.b c-d\ne.f g-h", keys: "jdaWk.", text: "c-d\ng-h", want: Position{0, 0}, reg: anyReg},
		{name: "empty line: jdiWk.", content: "abc\n\ndef", keys: "jdiWk.", text: "\n\ndef", want: Position{0, 0}, reg: anyReg},
		{name: "empty line: jciWZ<Esc>k.", content: "abc\n\ndef", keys: "jciWZ<Esc>k.", text: "Z\nZ\ndef", want: Position{0, 0}, reg: anyReg},
		{name: "empty line: jdiWj.", content: "abc\n\ndef", keys: "jdiWj.", text: "abc\n\n", want: Position{2, 0}, reg: anyReg},
	})
}

// TestWordObjectPunctuation checks iw and aw on punctuation and next to the
// indent. A run of punctuation is one word (a..b ldiw deletes ..), aw on it
// takes the blanks after it, or before it when none follow, and aw never
// takes the indent (  a.b lldaw deletes a).
